<template>
  <Loader />
</template>

<script lang="ts">
import cache from 'src/utils/cache';
import { LocalStorage } from 'quasar';
import { defineComponent } from 'vue';
import Loader from '../components/Loader.vue';
import { useUserStore, useAuthTokenStore } from 'src/store/main';
import { resolveExpiresInSeconds } from 'src/utils/sso-token';

// Fallback session length (seconds) if an older auth build omits expires_in from
// the redirect; mirrors the backend default (create_oauth_token: 86400). MAR-41.
const SSO_TOKEN_FALLBACK_SECONDS = 24 * 60 * 60;

export default defineComponent({
  el: '#validate-token',
  mixins: [cache],
  components: {
    Loader,
  },
  mounted() {
    if (this.$route.params.token === 'logout') {
      this.logout();
    } else {
      // clear old user data if any
      this.clearStorageForLogout();
      this.proceed();
    }
  },
  methods: {
    async proceed() {
      const source = this.$route.query.source;
      const token = String(this.$route.params.token);

      // Use the real lifetime auth sends in the redirect; fall back only if absent.
      const expires_in = resolveExpiresInSeconds(
        this.$route.query.expires_in,
        SSO_TOKEN_FALLBACK_SECONDS,
      );
      const expire_time = new Date(Date.now() + expires_in * 1000);
      const tokenDetails = {
        access_token: token,
        expires_in,
        scope: 'profile',
        token_type: 'Bearer',
        expire_time,
      };

      LocalStorage.set('token_details', tokenDetails);
      LocalStorage.set('login_source', source);

      // set new token in the store (raw token, never prefix with "Bearer ")
      await this.setAuthToken(token);

      // Cross-region detection runs in the router guard for /prepare-dashboard
      // (src/router/index.ts) so every login path — email/password, social,
      // and this token callback — is covered by a single chokepoint.
      this.$router.push('/prepare-dashboard');
    },
  },
  setup() {
    const auth_token_store = useAuthTokenStore();
    auth_token_store.$reset();
    const { setAuthToken } = auth_token_store;

    const user_store = useUserStore();
    const { getProfile } = user_store;
    return {
      getProfile,
      setAuthToken,
    };
  },
});
</script>
