/**
 * Resolve an SSO/social session lifetime (seconds) from the auth redirect's
 * `expires_in` value, falling back when it is absent or invalid (MAR-41).
 */
export function resolveExpiresInSeconds(
  rawExpiresIn: unknown,
  fallbackSeconds: number,
): number {
  const n = Number(rawExpiresIn);
  return Number.isFinite(n) && n > 0 ? n : fallbackSeconds;
}
